	std::span<const WmaCoefficientTableEntry> WmaCoefficientTable(WmaCoefficientBook book) {
		switch (book) {
		case WmaCoefficientBook::SetOneMain:
			return kSetOneMain;
		case WmaCoefficientBook::SetOneAlternate:
			return kSetOneAlternate;
		case WmaCoefficientBook::SetTwoMain:
			return kSetTwoMain;
		case WmaCoefficientBook::SetTwoAlternate:
			return kSetTwoAlternate;
		case WmaCoefficientBook::SetThreeMain:
			return kSetThreeMain;
		case WmaCoefficientBook::SetThreeAlternate:
			return kSetThreeAlternate;
		default:
			throw std::runtime_error("Unknown WMA Standard coefficient book");
		}
	}

